# تابع معمولی مناسب
def process_student(student):
    """پردازش اطلاعات دانشجو"""
    result = {
        'name': student['name'].title(),
        'grade': 'A' if student['score'] >= 90 else 'B',
        'passed': student['score'] >= 60
    }
    return result

students = [
    {'name': 'ali', 'score': 95},
    {'name': 'sara', 'score': 78}
]

for s in students:
    print(process_student(s))
